ALTER POLICY brain_zip_storage_read ON storage.objects USING (bucket_id = 'project-brain-zips' AND (storage.foldername(storage.objects.name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id::text = (storage.foldername(storage.objects.name))[2] AND p.user_id = auth.uid()));
ALTER POLICY brain_zip_storage_insert ON storage.objects WITH CHECK (bucket_id = 'project-brain-zips' AND (storage.foldername(storage.objects.name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id::text = (storage.foldername(storage.objects.name))[2] AND p.user_id = auth.uid()));
ALTER POLICY brain_zip_storage_delete ON storage.objects USING (bucket_id = 'project-brain-zips' AND (storage.foldername(storage.objects.name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id::text = (storage.foldername(storage.objects.name))[2] AND p.user_id = auth.uid()));